B.arm=new A.A("Bu gizlilik politikas\u0131 Yeni Asya uygulamas\u0131 i\xe7in haz\u0131rlanm\u0131\u015ft\u0131r.",null,B.dw,null,null,null,null,null,null,null,null)
B.aO=new A.cr(null,20,null,null)
B.atZ=new A.A("Toplanan Veriler",null,B.dv,null,null,null,null,null,null,null,null)
B.asi=new A.A("Uygulama, hizmeti sunmak ve geli\u015ftirmek i\xe7in gerekli olabilecek temel bilgileri i\u015fleyebilir. Bu kapsamda uygulama i\xe7i etkile\u015fimler, cihaz ve kullan\u0131m verileri ile kullan\u0131c\u0131 taraf\u0131ndan payla\u015f\u0131lan bilgiler de\u011ferlendirilebilir.",null,B.dw,null,null,null,null,null,null,null,null)
B.atq=new A.A("Verilerin \u0130\u015flenme Ama\xe7lar\u0131",null,B.dv,null,null,null,null,null,null,null,null)
B.ar6=new A.A("1) Uygulaman\u0131n \xe7al\u0131\u015ft\u0131r\u0131lmas\u0131 ve temel fonksiyonlar\u0131n sa\u011flanmas\u0131.\n2) Hata tespiti, performans iyile\u015ftirmeleri ve kullan\u0131c\u0131 deneyiminin geli\u015ftirilmesi.\n3) Destek taleplerinin y\xf6netimi ve ileti\u015fim s\xfcre\xe7lerinin y\xfcr\xfct\xfclmesi.",null,B.dw,null,null,null,null,null,null,null,null)
B.as9=new A.A("Hukuki Sebep",null,B.dv,null,null,null,null,null,null,null,null)
B.atI=new A.A("Ki\u015fisel veriler, y\xfcr\xfcrl\xfckteki mevzuata uygun olarak; s\xf6zle\u015fmenin kurulmas\u0131 veya ifas\u0131, hukuki y\xfck\xfcml\xfcl\xfcklerin yerine getirilmesi ve me\u015fru menfaat kapsam\u0131nda i\u015flenebilir.",null,B.dw,null,null,null,null,null,null,null,null)
B.atO=new A.A("Verilerin Aktar\u0131m\u0131",null,B.dv,null,null,null,null,null,null,null,null)
B.ave=new A.A("Veriler, hizmetin sunulmas\u0131 i\xe7in gerekli olmas\u0131 halinde ve ilgili mevzuata uygun \u015fekilde s\u0131n\u0131rl\u0131 olarak i\u015f ortaklar\u0131 veya teknik hizmet sa\u011flay\u0131c\u0131larla payla\u015f\u0131labilir.",null,B.dw,null,null,null,null,null,null,null,null)
B.atG=new A.A("Veri G\xfcvenli\u011fi",null,B.dv,null,null,null,null,null,null,null,null)
B.aty=new A.A("Ki\u015fisel verilerin g\xfcvenli\u011fi i\xe7in uygun teknik ve idari tedbirler uygulan\u0131r. Buna ra\u011fmen, internet \xfczerinden yap\u0131lan veri aktar\u0131m\u0131n\u0131n tamamen g\xfcvenli oldu\u011fu garanti edilemez.",null,B.dw,null,null,null,null,null,null,null,null)
B.arT=new A.A("Saklama S\xfcresi",null,B.dv,null,null,null,null,null,null,null,null)
B.ar_=new A.A("Veriler, i\u015fleme ama\xe7lar\u0131 i\xe7in gerekli olan s\xfcre boyunca ve ilgili mevzuatta \xf6ng\xf6r\xfclen saklama s\xfcrelerine uygun \u015fekilde muhafaza edilir.",null,B.dw,null,null,null,null,null,null,null,null)
B.at8=new A.A("Kullan\u0131c\u0131 Haklar\u0131",null,B.dv,null,null,null,null,null,null,null,null)
B.atY=new A.A("Ki\u015fisel verilerinizle ilgili olarak bilgi talep etme, d\xfczeltme, silme ve itiraz etme gibi haklara sahipsiniz. Taleplerinizi a\u015fa\u011f\u0131daki ileti\u015fim kanallar\u0131ndan iletebilirsiniz.",null,B.dw,null,null,null,null,null,null,null,null)
B.arj=new A.A("De\u011fi\u015fiklikler",null,B.dv,null,null,null,null,null,null,null,null)
B.arH=new A.A("Bu politika zaman zaman g\xfcncellenebilir. G\xfcncellemeler bu sayfada yay\u0131mlan\u0131r.",null,B.dw,null,null,null,null,null,null,null,null)
B.au4=new A.A("\u0130leti\u015fim",null,B.dv,null,null,null,null,null,null,null,null)
B.asF=new A.A("E-posta: app@yeniasya.com.tr\nTelefon: 0 (212) 655 88 59\nAdres: 15 Temmuz Mah., 1508 Sk., No: 3, 34212, G\xfcne\u015fli, \u0130stanbul",null,B.dw,null,null,null,null,null,null,null,null)
